export class TypeCache {
    /**
     * @param {string} typRegex
     */
    cacheType(typRegex: string): void;
    isTypeCacheEmpty(): boolean;
    /**
     * @param {{ name: string }} typeToCheck
     */
    isTypeAllowed(typeToCheck: {
        name: string;
    }): boolean;
    getCachedTypes(): string[];
    clearCache(): number;
}
